  uniform float uStrength;   // displacement strength (try 0.01)
  uniform float uFalloff;    // cursor influence radius in UV (try 0.2)
  uniform float uActive;     // 0 = no effect, 1 = full effect (for fade-in)

  varying vec2 vUv;

  void main() {
    // Distance from this fragment to the cursor (in UV space)
    float dist = distance(vUv, uMouse);

    // Influence curve: 1 near cursor, 0 past uFalloff
    float influence = (1.0 - smoothstep(0.0, uFalloff, dist)) * uActive;

    // Direction from cursor to this fragment — R/B get pushed along this
    vec2 dir = normalize(vUv - uMouse + vec2(0.0001));
    vec2 push = dir * influence * uStrength;

    // Per-channel UV offsets
    // R pushed away, B pulled in, G barely moves
    vec2 uvR = vUv + push;
    vec2 uvG = vUv + (push / 10.0);
    vec2 uvB = vUv - push;

    // Sample each channel at its offset UV
    vec4 sampleR = texture2D(uMap, uvR);
    vec4 sampleG = texture2D(uMap, uvG);
    vec4 sampleB = texture2D(uMap, uvB);

    // Compose final color: take R from R-sample, G from G-sample, B from B-sample
    vec3 col = vec3(sampleR.r, sampleG.g, sampleB.b);

    // Alpha: max of the three so the shape edge follows the widest channel
    float alpha = max(max(sampleR.a, sampleG.a), sampleB.a);

    gl_FragColor = vec4(col, alpha);
  }
